var a=Object.defineProperty;var o=(n,e)=>{for(var t in e)a(n,t,{get:e[t],enumerable:!0})};var h=[{text:"Measuring a device: add `?bench` to the VirtuHome panel's address (`/virtuhome?bench`) and it times the first frame, turning the house and a floor, and tapping rooms, then shows the numbers and writes them to Home Assistant's logbook. For reporting how a tablet does.",anchor:null},{text:"**Try it free** under **Available extensions** (Edit \u2192 **Extras**): an extension that can be tried works in the home for its trial days with no key, beside any licence, shows the days left, and stops at the end with a note in **Check my setup**. Once per extension and Home Assistant.",anchor:"extensions-and-licence-keys"},{text:"Washing machines, dryers and dishwashers link to their appliance (Home Connect, Miele, LG ThinQ, SmartThings, a running sensor or a smart plug's power): the display glows while it runs and a label says the programme and time left, **Paused**, **Done** or **Needs attention**. Smart Setup links one already drawn to the appliance named like it.",anchor:"by-hand"},{text:"VirtuHome's problems in Home Assistant's **Settings \u2192 System \u2192 Repairs**: the dashboard card's resource missing (with a fix), links to entities that are gone, an extension that can't load, and a licence that hasn't renewed for 30 days. Each goes away once it's put right.",anchor:"troubleshooting"},{text:"Help where you need it: a **?** on each sheet and beside the editor's tabs opens that part of the guide; first-time hints, once each (Edit \u2192 **Home** \u2192 **Show hints again**); and **What's new** after an update, once, for administrators in the sidebar (Edit \u2192 **Home** \u2192 **What's new**).",anchor:"find-your-way-around"},{text:"German and Dutch: everything VirtuHome shows, and Home Assistant's own screens for it (setting up, options, Repairs), follow the language in your Home Assistant profile. Numbers follow it too.",anchor:null}];export{o as a,h as b};
